begin;
-- Só nesta transação descartável: permite testar o preparo mesmo depois da data real.
create or replace function private.teste_visivel() returns boolean language sql stable set search_path='' as $$select true$$;
do $$begin
 if private.preparar_catalogo_teste_lancamento()<>18 then raise exception 'FAIL demo 18';end if;
 if(select count(*) from public.produtos where codigo like 'RM-C%' and dado_teste and status_catalogo='publicado' and ativo)<>18 then raise exception 'FAIL 18 marcadas';end if;
 if(select count(*) from public.variacoes v join public.produtos p on p.id=v.produto_id where p.codigo like 'RM-C%' and v.ativo and estoque_fisico=1 and tamanho='48' and cor='Demonstração')<>18 then raise exception 'FAIL estoque demo';end if;
 if not(select arquivado_em is not null from public.produtos where codigo='HOM-RM99') then raise exception 'FAIL limpeza confirmada';end if;
 if not(select nome='Coleção de lançamento' and not dado_teste from public.colecoes where atual) then raise exception 'FAIL coleção compartilhada';end if;
 if private.preparar_catalogo_teste_lancamento()<>18 then raise exception 'FAIL repetir demo';end if;
 if(select count(*) from public.variacoes v join public.produtos p on p.id=v.produto_id where p.codigo like 'RM-C%' and v.ativo)<>18 then raise exception 'FAIL variações duplicadas';end if;
 if(select count(*) from storage.objects where bucket_id='produtos-publico')<>18 then raise exception 'FAIL fotos removidas antes da carga';end if;
 raise notice 'PASS: demo 1 dezoito peças rastreáveis, uma unidade cada, fotos preservadas, limpeza e repetição segura';
end$$;
select private.arquivar_dados_teste();
do $$begin
 if exists(select 1 from public.produtos where dado_teste and arquivado_em is null) then raise exception 'FAIL teste ainda não arquivado';end if;
 if exists(select 1 from public.variacoes v join public.produtos p on p.id=v.produto_id where p.dado_teste and v.arquivado_em is null) then raise exception 'FAIL var teste visível';end if;
 if(select count(*) from storage.objects where bucket_id='produtos-publico')<>18 then raise exception 'FAIL fotos antigas não preservadas até carga';end if;
 raise notice 'PASS: demo 2 encerramento arquiva peça e estoque sem apagar fotos ou histórico';
end$$;
rollback;
